import bruzem

def _extract_numeric(obj):
    """Extract a numeric (int or float) value from the object returned by bruzem.find."""
    if isinstance(obj, (int, float)):
        return obj
    if isinstance(obj, tuple):
        # Return the first numeric element in the tuple
        for item in obj:
            if isinstance(item, (int, float)):
                return item
        raise TypeError(f"No numeric value found in tuple {obj}")
    # Check common attribute names
    for attr in ("value", "data"):
        if hasattr(obj, attr):
            val = getattr(obj, attr)
            if isinstance(val, (int, float)):
                return val
    raise AttributeError(f"Unable to locate numeric value in object of type {type(obj)}")

# Retrieve raw objects
